//! FIX 4.4 dictionary tables, generated by build.rs from specs/fix44.yaml.

/// Set of tags, one bit per tag below 16384 (2 KB).
#[derive(Debug)]
pub struct TagSet(pub [u64; 256]);

impl TagSet {
    #[inline(always)]
    pub fn contains(&self, tag: u16) -> bool {
        let word = (tag / 64) as usize;
        word < self.0.len() && (self.0[word] >> (tag % 64)) & 1 != 0
    }
}

/// Set of tags in `base..base + 64 * bits.len()`, one bit per tag. For
/// group members, which cluster in a few words.
#[derive(Debug)]
pub struct TagRange {
    pub base: u16,
    pub bits: &'static [u64],
}

impl TagRange {
    #[inline(always)]
    pub fn contains(&self, tag: u16) -> bool {
        // Below `base` wraps past any range a tag below 16384 can need.
        let bit = tag.wrapping_sub(self.base) as usize;
        let word = bit / 64;
        word < self.bits.len() && (self.bits[word] >> (bit % 64)) & 1 != 0
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FieldType {
    String, Char, Int, Length, SeqNum, NumInGroup, Boolean, UtcTimestamp, Data,
    Float, Price, Qty, Amt, Currency, Exchange, LocalMktDate, UtcDateOnly,
    UtcTimeOnly, MonthYear, MultipleValueString, Country, Percentage, PriceOffset,
}

#[derive(Debug)]
pub struct FieldDef {
    pub tag: u16,
    pub name: &'static str,
    pub ty: FieldType,
    /// Allowed wire values; empty means any.
    pub values: &'static [&'static [u8]],
}

/// StandardHeader or StandardTrailer.
#[derive(Debug)]
pub struct SectionSpec {
    /// Top-level tags of the section, group count tags included. Group
    /// members are in the GroupSpecs.
    pub tags: TagSet,
    pub required: &'static [u16],
    pub groups: &'static [&'static GroupSpec],
}

#[derive(Debug)]
pub struct MessageSpec {
    pub name: &'static str,
    pub msg_type: &'static [u8],
    /// Session-level message.
    pub admin: bool,
    /// Top-level body tags, group count tags included. Group members are in
    /// the GroupSpecs; header and trailer are separate.
    pub tags: TagSet,
    /// Required body tags (group-internal requirements live on the GroupSpec).
    pub required: &'static [u16],
    pub groups: &'static [&'static GroupSpec],
}

/// Layout of one repeating group. Generated from the spec.
#[derive(Debug)]
pub struct GroupSpec {
    /// NumInGroup tag, e.g. 268 NoMDEntries.
    pub count_tag: u16,
    /// First field of every entry, e.g. 269 MDEntryType.
    pub delimiter: u16,
    /// Every tag that may appear inside an entry, nested groups' tags included.
    pub members: &'static [u16],
    /// `members` as a bitset, for `is_member`.
    pub member_set: TagRange,
    /// Tags every entry must have.
    pub required: &'static [u16],
    /// Groups nested directly inside an entry.
    pub groups: &'static [&'static GroupSpec],
}

impl GroupSpec {
    #[inline(always)]
    pub(super) fn is_member(&self, tag: u16) -> bool {
        self.member_set.contains(tag)
    }
}

include!(concat!(env!("OUT_DIR"), "/fix44.rs"));

/// Field definition by tag.
pub fn field(tag: u16) -> Option<&'static FieldDef> {
    FIELDS.binary_search_by_key(&tag, |f| f.tag).ok().map(|i| &FIELDS[i])
}


#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tag_constants() {
        assert_eq!(tags::BEGIN_STRING, 8);
        assert_eq!(tags::SENDER_COMP_ID, 49);
        assert_eq!(tags::MSG_SEQ_NUM, 34);
        assert_eq!(tags::HEART_BT_INT, 108);
        assert_eq!(tags::NO_MSG_TYPES, 384);
        assert_eq!(tags::XML_DATA_LEN, 212);
    }

    #[test]
    fn enums_round_trip() {
        assert_eq!(MsgType::Logon.as_bytes(), b"A");
        assert_eq!(MsgType::from_bytes(b"0"), Some(MsgType::Heartbeat));
        assert_eq!(MsgType::from_bytes(b"Z"), None);
        assert_eq!(SessionRejectReason::CompIdProblem.as_bytes(), b"9");
        assert_eq!(SessionRejectReason::from_bytes(b"99"), Some(SessionRejectReason::Other));
        assert_eq!(SessionRejectReason::TAG, 373);
        assert_eq!(MsgDirection::from_bytes(b"S"), Some(MsgDirection::Send));
    }

    #[test]
    fn field_lookup() {
        let f = field(108).unwrap();
        assert_eq!((f.name, f.ty), ("HeartBtInt", FieldType::Int));
        assert_eq!(field(98).unwrap().values.len(), 7);
        assert!(field(9999).is_none());
        assert!(FIELDS.windows(2).all(|w| w[0].tag < w[1].tag));
    }

    #[test]
    fn header_and_trailer() {
        for tag in [8, 9, 35, 49, 56, 34, 52, 43, 122, 627] {
            assert!(HEADER.tags.contains(tag), "{tag}");
        }
        assert!(!HEADER.tags.contains(108));
        // Group members live on the GroupSpec.
        assert!(!HEADER.tags.contains(628));
        assert_eq!(HEADER.required, &[8, 9, 35, 49, 56, 34, 52]);
        assert_eq!(HEADER.groups.len(), 1);
        let hops = HEADER.groups[0];
        assert_eq!((hops.count_tag, hops.delimiter, hops.members), (627, 628, &[628u16, 629, 630][..]));
        assert_eq!(TRAILER.required, &[10]);
    }

    #[test]
    fn messages() {
        let logon = message(b"A").unwrap();
        assert_eq!((logon.name, logon.admin), ("Logon", true));
        assert_eq!(logon.required, &[98, 108]);
        for tag in [98, 108, 141, 384, 553, 554] {
            assert!(logon.tags.contains(tag), "{tag}");
        }
        assert!(!logon.tags.contains(385));
        // Header tags aren't part of the body set.
        assert!(!logon.tags.contains(49));
        assert_eq!(logon.groups[0].count_tag, 384);
        assert_eq!(logon.groups[0].delimiter, 372);

        assert_eq!(message(b"1").unwrap().required, &[112]);
        assert_eq!(message(b"2").unwrap().required, &[7, 16]);
        assert!(message(b"V").is_none());
        for defined in [&b"0"[..], b"V", b"z", b"AA", b"BH", b"U1", b"UFOO"] {
            assert!(is_defined_msg_type(defined), "{}", String::from_utf8_lossy(defined));
        }
        for undefined in [&b""[..], b"I", b"O", b"BI", b"ZZ", b"VV", b"u1"] {
            assert!(!is_defined_msg_type(undefined), "{}", String::from_utf8_lossy(undefined));
        }
        assert!(MESSAGES.iter().all(|m| is_defined_msg_type(m.msg_type)));
        assert_eq!(MESSAGES.len(), 13);
        assert_eq!(MESSAGES.iter().filter(|m| m.admin).count(), 7);

        let order = message(b"D").unwrap();
        assert_eq!((order.name, order.admin), ("NewOrderSingle", false));
        assert_eq!(order.required, &[11, 55, 54, 60, 38, 40]);
        let parties = order.groups[0];
        assert_eq!((parties.count_tag, parties.delimiter, parties.groups[0].count_tag), (453, 448, 802));
        assert!(parties.is_member(523) && parties.groups[0].is_member(523) && !parties.groups[0].is_member(448));
        assert_eq!(message(b"j").unwrap().required, &[372, 380]);
        assert!(!message(b"0").unwrap().tags.contains(386));
    }

    #[test]
    fn tag_set_bounds() {
        assert!(!HEADER.tags.contains(u16::MAX));
        assert!(!HEADER.tags.contains(0));
    }

    /// Every generated group's `member_set` holds exactly its `members`.
    #[test]
    fn member_sets_match_members() {
        fn check(group: &GroupSpec) {
            for tag in 0..=u16::MAX {
                assert_eq!(group.member_set.contains(tag), group.members.contains(&tag), "{} tag {tag}", group.count_tag);
            }
            group.groups.iter().for_each(|g| check(g));
        }
        let sections = [HEADER.groups, TRAILER.groups];
        let bodies = MESSAGES.iter().map(|m| m.groups);
        let all: Vec<_> = sections.into_iter().chain(bodies).flatten().collect();
        assert!(!all.is_empty());
        all.into_iter().for_each(|g| check(g));
    }
}
